    private static EntityRow ToRow(AccidentListItemResponse accident) => new()
    {
        Id = accident.Id,
        Status = accident.InjuryPercentage >= 70 ? "شدید" : accident.InjuryPercentage >= 30 ? "متوسط" : "ثبت‌شده",
        StatusTone = RmsUi.InjuryTone(accident.InjuryPercentage),
        Values = new()
        {
            ["Code"] = $"ACC-{RmsUi.ShortId(accident.Id)}",
            ["Road"] = accident.RoadName,
            ["Type"] = RmsUi.AccidentType(accident.AccidentType),
            ["Weather"] = RmsUi.Weather(accident.Weather),
            ["People"] = $"{accident.PeopleCount.ToString().TranslateDigits()} نفر",
            ["Date"] = RmsUi.DateTime(accident.AccidentTimeUnix),
        }
    };

    private static IReadOnlyDictionary<string, string> ToDraft(AccidentResponse accident) =>
        new Dictionary<string, string>
        {
            ["Road"] = accident.FkIdRoad.ToString(),
            ["Date"] = RmsUi.DateTimeInput(accident.AccidentTimeUnix),
            ["Latitude"] = accident.Latitude.ToString(System.Globalization.CultureInfo.InvariantCulture),
            ["Longitude"] = accident.Longitude.ToString(System.Globalization.CultureInfo.InvariantCulture),
            ["Weather"] = Convert.ToByte(accident.Weather).ToString(),
            ["RoadCondition"] = Convert.ToByte(accident.RoadCondition).ToString(),
            ["Lighting"] = Convert.ToByte(accident.LightingCondition).ToString(),
            ["Sign"] = Convert.ToByte(accident.TrafficSignCondition).ToString(),
            ["Cause"] = Convert.ToByte(accident.AccidentCause).ToString(),
            ["Type"] = Convert.ToByte(accident.AccidentType).ToString()
        };

    private static LookupOption[] EnumOptions<TEnum>(Func<TEnum, string> label)
        where TEnum : struct, Enum => Enum.GetValues<TEnum>()
